// Elasticsearch index contract shared by the outbox poller (the only writer)
// and Search Service (the only reader) — same drift risk as the Redis key
// naming in availability.js, same fix: one definition, not two guesses that
// happen to agree today.

export const SEARCH_INDEX = "events";

// "conc" finding "Concert" needs prefix matching; a one-character typo needs
// edit-distance tolerance. These are two different mechanisms and neither
// alone covers both acceptance criteria, so every text field gets both:
//   - the base field, analyzed with the `standard` analyzer, queried with
//     fuzziness at query time for typo tolerance;
//   - a `.autocomplete` subfield, indexed with an edge-ngram tokenizer (so
//     "concert" is stored as the terms c/co/con/conc/.../concert), queried
//     WITHOUT fuzziness because the prefix is already a real indexed term —
//     adding fuzziness on top of ngrams would blow up the candidate set for
//     no benefit.
// The search-time analyzer for the autocomplete field is deliberately plain
// `standard` (not edge-ngram) — ngram-ing the query itself would generate every
// prefix of what the user typed and match on all of them, which is correct only
// when *indexing*; at *query* time it would turn a 3-character query into a
// fuzzy OR of "c", "co", "con" against a field already full of ngrams, matching
// almost everything.
const AUTOCOMPLETE_ANALYZER = "autocomplete_index";
const AUTOCOMPLETE_SEARCH_ANALYZER = "autocomplete_search";

export const SEARCH_INDEX_SETTINGS = {
    analysis: {
        tokenizer: {
            autocomplete_tokenizer: {
                type: "edge_ngram",
                min_gram: 1,
                max_gram: 20,
                token_chars: ["letter", "digit"],
            },
        },
        analyzer: {
            [AUTOCOMPLETE_ANALYZER]: {
                type: "custom",
                tokenizer: "autocomplete_tokenizer",
                filter: ["lowercase"],
            },
            [AUTOCOMPLETE_SEARCH_ANALYZER]: {
                type: "custom",
                tokenizer: "standard",
                filter: ["lowercase"],
            },
        },
    },
};

const autocompleteText = () => ({
    type: "text",
    fields: {
        autocomplete: {
            type: "text",
            analyzer: AUTOCOMPLETE_ANALYZER,
            search_analyzer: AUTOCOMPLETE_SEARCH_ANALYZER,
        },
    },
});

export const SEARCH_INDEX_MAPPINGS = {
    properties: {
        id: { type: "keyword" },
        name: autocompleteText(),
        description: { type: "text" },
        venueId: { type: "keyword" },
        venueName: autocompleteText(),
        venueLocation: { type: "text" },
        performerId: { type: "keyword" },
        performerName: autocompleteText(),
        eventDate: { type: "date" },
    },
};

// Idempotent index creation, shared so Search Service (the reader) and the
// outbox poller (the writer) can never define the mapping differently —
// whichever process boots first creates it, the other's call is a no-op.
export const ensureSearchIndex = async (esClient) => {
    const exists = await esClient.indices.exists({ index: SEARCH_INDEX });
    if (exists) return;
    try {
        await esClient.indices.create({
            index: SEARCH_INDEX,
            settings: SEARCH_INDEX_SETTINGS,
            mappings: SEARCH_INDEX_MAPPINGS,
        });
    } catch (err) {
        if (err.meta?.body?.error?.type !== "resource_already_exists_exception") {
            throw err;
        }
    }
};

// The event's own id IS the document id — deterministic, not autogenerated.
// Re-indexing the same event twice (a retried poller batch, a re-processed
// outbox row after a crash) is then an overwrite, never a duplicate document.
// This is the whole mechanism behind "at-least-once delivery + idempotent
// indexing": at-least-once is fine to build when the operation it retries is
// naturally idempotent, and a deterministic id is what makes ES PUT idempotent.
export const searchDocId = (eventId) => String(eventId);

// Payload -> ES document. Deliberately narrow — only the fields the search
// query above can actually match against or filter on. venueName/venueLocation/
// performerName are expected to already be denormalized onto the payload by the
// writer (see event.service.js) — this function does not itself reach into
// Postgres to look them up, keeping it a pure, dependency-free mapping callable
// from both the poller and any test.
export const toSearchDocument = (event) => ({
    id: String(event.id),
    name: event.name,
    description: event.description ?? "",
    venueId: event.venueId != null ? String(event.venueId) : null,
    venueName: event.venueName ?? "",
    venueLocation: event.venueLocation ?? "",
    performerId: event.performerId != null ? String(event.performerId) : null,
    performerName: event.performerName ?? "",
    eventDate: event.eventDate,
});
